pub const NODE_OUT: usize = 0;
pub const NODE_NODE_HP: usize = 1;
pub const NODE_BASE3: usize = 2;
pub const NODE_NODE_LP: usize = 3;
pub const NODE_EMIT3: usize = 4;
pub const NODE_VCC: usize = 5;
pub const NODE_LEDA: usize = 6;
pub const NODE_LEDK: usize = 7;

pub const VSOURCE_V1_RHS_ROW: usize = 8;

/// Node names in DC_OP index order — `NODE_NAMES[i]` is the netlist name of the
/// node whose baked operating point is `DC_OP[i]` (openfarf thread 218). Rows
/// with no node name (augmented voltage-source / inductor branch-current rows)
/// are `""`. Use `dc_op_by_name` for a name→voltage lookup.
pub const NODE_NAMES: [&str; N] = [
    "out", "node_hp", "base3", "node_lp", "emit3", "vcc", "leda", "ledk", "",
];

/// Look up a node's baked DC operating-point voltage by its netlist name.
///
/// `dc_op_by_name("plate1")` returns `Some(DC_OP[NODE_PLATE1])` — the index in
/// `NODE_NAMES` is the SAME index used in `DC_OP`. `None` for an unknown name or
/// an unnamed (augmented VS / inductor branch) row. Linear scan over `N`; call
/// it off the audio thread.
pub fn dc_op_by_name(name: &str) -> Option<f64> {
    let mut i = 0;
    while i < N {
        if !NODE_NAMES[i].is_empty() && NODE_NAMES[i] == name {
            return Some(DC_OP[i]);
        }
        i += 1;
    }
    None
}

