/// Fast exp() for audio circuit simulation.
/// Input clamped to [-40, 40] (matches melange safe_exp convention).
///
/// Default: polynomial approximation (<0.0004% error, ~6x faster than libm).
/// To use hardware/libm exp, compile with: `--cfg melange_precise_exp`
#[inline(always)]
fn fast_exp(x: f64) -> f64 {
    #[cfg(melange_precise_exp)]
    {
        x.clamp(-40.0, 40.0).exp()
    }
    #[cfg(not(melange_precise_exp))]
    {
        // Range reduction + 5th-order minimax polynomial. <0.0004% max relative error.
        // No lookup tables, no libm dependency, branchless hot path.
        let x = x.clamp(-40.0, 40.0);
        const LN2_INV: f64 = std::f64::consts::LOG2_E;
        const LN2_HI: f64 = 0.6931471803691238;
        const LN2_LO: f64 = 1.9082149292705877e-10;
        const SHIFT: f64 = 6755399441055744.0; // 2^52 + 2^51
        let z = x * LN2_INV + SHIFT;
        let n_i64 = z.to_bits() as i64 - SHIFT.to_bits() as i64;
        let n = n_i64 as f64;
        let f = (x - n * LN2_HI) - n * LN2_LO;
        let p = 1.0
            + f * (1.0
                + f * (0.5
                    + f * (0.16666666666666607
                        + f * (0.04166666666665876 + f * 0.008333333333492337))));
        let pow2n = f64::from_bits(((1023 + n_i64) as u64) << 52);
        p * pow2n
    }
}

/// Fast ln() for audio circuit simulation.
/// Symmetric log series (~0.005% max relative error, ~3x faster than libm).
/// Only valid for positive inputs.
#[inline(always)]
fn fast_ln(x: f64) -> f64 {
    #[cfg(melange_precise_exp)]
    {
        x.ln()
    }
    #[cfg(not(melange_precise_exp))]
    {
        // Extract exponent and mantissa from IEEE 754 double
        let bits = x.to_bits();
        let e = ((bits >> 52) & 0x7FF) as i64 - 1023;
        // Normalize mantissa to [1, 2)
        let m_bits = (bits & 0x000F_FFFF_FFFF_FFFF) | 0x3FF0_0000_0000_0000;
        let m = f64::from_bits(m_bits);
        // Symmetric log series: u = (m-1)/(m+1), ln(m) = 2u(1 + u²/3 + u⁴/5 + u⁶/7)
        // For m in [1,2), u in [0,1/3): converges much faster than Taylor.
        let u = (m - 1.0) / (m + 1.0);
        let u2 = u * u;
        let ln_m =
            2.0 * u * (1.0 + u2 * (0.3333333333333333 + u2 * (0.2 + u2 * 0.14285714285714285)));
        ln_m + (e as f64) * std::f64::consts::LN_2
    }
}

// Canonical source: melange-primitives/src/nr.rs (pnjlim, fetlim)
// Duplicated here because generated code must be self-contained.

/// SPICE PN junction voltage limiting (from SPICE3f5 DEVpnjlim).
///
/// Limits large forward voltage steps on exponential I-V curves using
/// logarithmic compression. Only activates when vnew > vcrit with large step.
#[inline(always)]
fn pnjlim(vnew: f64, vold: f64, vt: f64, vcrit: f64) -> f64 {
    if vnew > vcrit && (vnew - vold).abs() > vt + vt {
        if vold >= 0.0 {
            let arg = 1.0 + (vnew - vold) / vt;
            if arg > 0.0 {
                vold + vt * arg.ln()
            } else {
                vcrit
            }
        } else {
            vt * (vnew / vt).ln()
        }
    } else {
        vnew
    }
}

/// SPICE FET voltage limiting (from SPICE3f5 DEVfetlim).
///
/// Prevents gate-source voltage from jumping across threshold boundary.
/// The allowed step size adapts to the distance from threshold.
#[inline(always)]
fn fetlim(vnew: f64, vold: f64, vto: f64) -> f64 {
    let delv = vnew - vold;
    let vtox = vto + 3.5;
    // SPICE3f5 DEVfetlim (with Alan Gillespie's vtstlo fix):
    //   vtsthi = |2*(vold-vto)| + 2
    //   vtstlo = |vold-vto| + 1     (= vtsthi/2)
    let vtsthi = (2.0 * (vold - vto)).abs() + 2.0;
    let vtstlo = (vold - vto).abs() + 1.0;

    if vold >= vto {
        // Device is "on"
        if vold >= vtox {
            if delv <= 0.0 {
                // Going off
                if vnew >= vtox {
                    if -delv > vtstlo {
                        return vold - vtstlo;
                    }
                } else {
                    return vnew.max(vto + 2.0);
                }
            } else {
                // Staying on
                if delv >= vtsthi {
                    return vold + vtsthi;
                }
            }
        } else {
            // Middle region
            if delv <= 0.0 {
                return vnew.max(vto - 0.5);
            } else {
                return vnew.min(vto + 4.0);
            }
        }
    } else {
        // Device is "off"
        if delv <= 0.0 {
            // SPICE clamps the off/decreasing branch with vtsthi (NOT vtstlo)
            if -delv > vtsthi {
                return vold - vtsthi;
            }
        } else if vnew <= vto + 0.5 {
            if delv > vtstlo {
                return vold + vtstlo;
            }
        } else {
            return vto + 0.5;
        }
    }
    vnew
}

// Canonical source: melange-devices/src/diode.rs (DiodeShockley)
// Duplicated here because generated code must be self-contained.

/// Forward-current ceiling for the extended exponential region [A].
/// Above this the I-V curve continues as a linear extension (hard wall).
const DIODE_MAX_FWD_I: f64 = 1e3;

/// Diode current: i_d = is * (exp(v_d / n_vt) - 1)
///
/// Below -40·n_vt the current extends linearly with slope equal to the
/// clamped conductance, keeping value and derivative consistent (canonical
/// form: DiodeShockley::current_at in melange-devices). For -40·n_vt ≤ v_d ≤
/// 40·n_vt this is the legacy fast_exp path (bit-exact with prior behavior).
/// Above it, the true exponential continues in ln-current space
/// (is·e^x = e^(x + ln is), immune to exp overflow and the fast_exp ±40
/// clamp) until forward current reaches DIODE_MAX_FWD_I, then extends
/// linearly. Without this, extreme-IS models (wide-bandgap junctions,
/// IS=1e-30, Vf ≈ 3 V) have their conduction knee above the clamp and the
/// device is electrically absent at any voltage.
#[inline(always)]
fn diode_current(v_d: f64, is: f64, n_vt: f64) -> f64 {
    let x = v_d / n_vt;
    if x < -40.0 {
        // Deep reverse: linear extension consistent with diode_conductance
        // (matches canonical DiodeShockley::current_at in melange-devices).
        // A flat clamp here would return constant current while the
        // conductance stays nonzero — value/derivative inconsistency that
        // stalls NR in deep reverse bias.
        let exp_clamp = fast_exp(-40.0);
        let i_clamp = is * (exp_clamp - 1.0);
        let g_clamp = (is / n_vt) * exp_clamp;
        return i_clamp + g_clamp * (v_d + 40.0 * n_vt);
    }
    if x <= 40.0 {
        return is * (fast_exp(x) - 1.0);
    }
    // Cold path: beyond the legacy clamp (NR overshoot or wide-bandgap knee)
    let ln_is = is.ln();
    let y = x + ln_is; // ln of forward current
    let y_max = (40.0 + ln_is).max(DIODE_MAX_FWD_I.ln());
    if y <= y_max {
        y.exp() - is
    } else {
        let i_c = y_max.exp();
        (i_c - is) + i_c * (y - y_max)
    }
}

/// Diode conductance: g_d = di/dv = (is / n_vt) * exp(v_d / n_vt)
/// Matches the derivative of diode_current in all three regions.
#[inline(always)]
fn diode_conductance(v_d: f64, is: f64, n_vt: f64) -> f64 {
    let x = v_d / n_vt;
    if x <= 40.0 {
        return (is / n_vt) * fast_exp(x.max(-40.0));
    }
    let ln_is = is.ln();
    let y_max = (40.0 + ln_is).max(DIODE_MAX_FWD_I.ln());
    let y = (x + ln_is).min(y_max);
    y.exp() / n_vt
}

/// Solve V_j + I(V_j)*RS = V_d for the junction voltage V_j.
///
/// Scalar NR seeded at vcrit with pnjlim log-compressed steps. A flat
/// 4·n_vt step clamp from a 0.7 V seed cannot reach wide-bandgap knees
/// (Vf ≈ 3 V) within any reasonable iteration budget.
#[inline(always)]
fn diode_solve_vj(v_d: f64, is: f64, n_vt: f64, rs: f64) -> f64 {
    let vcrit = n_vt * (n_vt / (std::f64::consts::SQRT_2 * is)).ln();
    let mut v_j = if v_d > 0.0 { v_d.min(vcrit) } else { v_d };
    for _ in 0..32 {
        let id = diode_current(v_j, is, n_vt);
        let gd = diode_conductance(v_j, is, n_vt);
        let f = v_j + id * rs - v_d;
        let fp = 1.0 + gd * rs;
        let v_new = pnjlim(v_j - f / fp, v_j, n_vt, vcrit);
        let delta = v_new - v_j;
        v_j = v_new;
        if delta.abs() < 1e-10 {
            break;
        }
    }
    v_j
}

/// Diode with series resistance: solve V_j + I(V_j)*RS = V_d for V_j,
/// then return I(V_j).
#[inline(always)]
fn diode_current_with_rs(v_d: f64, is: f64, n_vt: f64, rs: f64) -> f64 {
    let v_j = diode_solve_vj(v_d, is, n_vt, rs);
    diode_current(v_j, is, n_vt)
}

/// Diode conductance with series resistance: g_total = g_j / (1 + g_j * rs)
/// where g_j is evaluated at the NR-solved junction voltage.
#[inline(always)]
fn diode_conductance_with_rs(v_d: f64, is: f64, n_vt: f64, rs: f64) -> f64 {
    let v_j = diode_solve_vj(v_d, is, n_vt, rs);
    let g_j = diode_conductance(v_j, is, n_vt);
    g_j / (1.0 + g_j * rs)
}

/// Diode with series resistance, fused: solve V_j once and return both the
/// current and the total conductance.
///
/// Exactly equivalent to calling `diode_current_with_rs` and
/// `diode_conductance_with_rs` with the same arguments — same `diode_solve_vj`
/// on the same inputs, same subsequent arithmetic in the same order — but the
/// inner scalar NR (up to 32 iterations) runs once instead of twice. The two
/// separate functions are kept for callers that need only one of the outputs.
///
/// `#[inline(always)]` on the split pair is not sufficient to get this for
/// free: `diode_solve_vj` has a data-dependent early `break`, and LLVM does not
/// CSE the duplicate call in practice (measured).
#[inline(always)]
fn diode_eval_with_rs(v_d: f64, is: f64, n_vt: f64, rs: f64) -> (f64, f64) {
    let v_j = diode_solve_vj(v_d, is, n_vt, rs);
    let g_j = diode_conductance(v_j, is, n_vt);
    (diode_current(v_j, is, n_vt), g_j / (1.0 + g_j * rs))
}

/// Reverse breakdown current: I_bv = -IBV * exp(-(v_d + BV) / n_vt)
/// Added to diode current when v_d < -BV.
#[inline(always)]
fn diode_breakdown_current(v_d: f64, n_vt: f64, bv: f64, ibv: f64) -> f64 {
    let x = (-(v_d + bv) / n_vt).clamp(-40.0, 40.0);
    -ibv * fast_exp(x)
}

/// Reverse breakdown conductance: dI_bv/dv = IBV/n_vt * exp(-(v_d + BV) / n_vt)
#[inline(always)]
fn diode_breakdown_conductance(v_d: f64, n_vt: f64, bv: f64, ibv: f64) -> f64 {
    let x = (-(v_d + bv) / n_vt).clamp(-40.0, 40.0);
    ibv / n_vt * fast_exp(x)
}

// Canonical source: melange-devices/src/bjt.rs (BjtEbersMoll, BjtGummelPoon)
// Duplicated here because generated code must be self-contained.

/// Safe exponential using fast_exp (clamp to prevent overflow, matches runtime [-40, 40] range)
#[inline(always)]
fn safe_exp(x: f64) -> f64 {
    fast_exp(x)
}

/// Combined BJT evaluation: returns (Ic, Ib, [dIc/dVbe, dIc/dVbc, dIb/dVbe, dIb/dVbc]).
///
/// Computes exp(Vbe/(NF*VT)) and exp(Vbc/(NR*VT)) once and shares them across current
/// and Jacobian calculations. Reduces from 8-10 exp() to 2-4 per evaluation.
#[inline(always)]
fn bjt_evaluate(
    vbe: f64,
    vbc: f64,
    is: f64,
    vt: f64,
    nf: f64,
    nr: f64,
    beta_f: f64,
    beta_r: f64,
    sign: f64,
    use_gp: bool,
    vaf: f64,
    var: f64,
    ikf: f64,
    ikr: f64,
    ise: f64,
    ne: f64,
    isc: f64,
    nc: f64,
) -> (f64, f64, [f64; 4]) {
    let vbe_eff = sign * vbe;
    let vbc_eff = sign * vbc;
    let nf_vt = nf * vt;
    let nr_vt = nr * vt;

    // Shared exponentials (computed once)
    let exp_be = safe_exp(vbe_eff / nf_vt);
    let exp_bc = safe_exp(vbc_eff / nr_vt);

    // ISE leakage exponential (computed once, only when needed)
    let exp_be_leak = if ise > 0.0 {
        safe_exp(vbe_eff / (ne * vt))
    } else {
        0.0
    };

    // ISC leakage exponential (computed once, only when needed)
    let exp_bc_leak = if isc > 0.0 {
        safe_exp(vbc_eff / (nc * vt))
    } else {
        0.0
    };

    // === Collector current ===
    let i_cc = is * (exp_be - exp_bc);

    // === Base current components ===
    let ib_fwd = is / beta_f * (exp_be - 1.0);
    let ib_rev = is / beta_r * (exp_bc - 1.0);
    let ib_leak_be = if ise > 0.0 {
        ise * (exp_be_leak - 1.0)
    } else {
        0.0
    };
    let ib_leak_bc = if isc > 0.0 {
        isc * (exp_bc_leak - 1.0)
    } else {
        0.0
    };

    // === Base current Jacobian (EM components) ===
    let dib_fwd_dvbe = (is / (beta_f * nf_vt)) * exp_be;
    let dib_rev_dvbc = (is / (beta_r * nr_vt)) * exp_bc;
    let dib_leak_dvbe = if ise > 0.0 {
        (ise / (ne * vt)) * exp_be_leak
    } else {
        0.0
    };
    let dib_leak_dvbc = if isc > 0.0 {
        (isc / (nc * vt)) * exp_bc_leak
    } else {
        0.0
    };

    if !use_gp {
        // Ebers-Moll
        let ic = sign * (i_cc - is / beta_r * (exp_bc - 1.0));
        let ib = sign * (ib_fwd + ib_rev + ib_leak_be + ib_leak_bc);
        let dic_dvbe = is / nf_vt * exp_be;
        let dic_dvbc = -(is / nr_vt) * exp_bc - (is / (beta_r * nr_vt)) * exp_bc;
        return (
            ic,
            ib,
            [
                dic_dvbe,
                dic_dvbc,
                dib_fwd_dvbe + dib_leak_dvbe,
                dib_rev_dvbc + dib_leak_dvbc,
            ],
        );
    }

    // Gummel-Poon — matches ngspice bjtload.c:565-630
    // q1 and derivatives
    let q1_denom = 1.0 - vbe_eff / var - vbc_eff / vaf;
    let (q1, dq1_dvbe, dq1_dvbc) = if q1_denom <= 0.0 || q1_denom.abs() < 1e-30 {
        (1.0, 0.0, 0.0)
    } else {
        let q1 = 1.0 / q1_denom;
        (q1, q1 * q1 / var, q1 * q1 / vaf)
    };

    // q2 = cbe/IKF + cbc/IKR with cbe = is*(exp_be - 1), cbc = is*(exp_bc - 1)
    // where exp_be/exp_bc already use NF*VT / NR*VT (shared with current calc above).
    // Matches ngspice bjtload.c:571.
    let cbe = is * (exp_be - 1.0);
    let cbc = is * (exp_bc - 1.0);
    let q2 = cbe / ikf + cbc / ikr;
    let dq2_dvbe = (is / (nf_vt * ikf)) * exp_be;
    let dq2_dvbc = (is / (nr_vt * ikr)) * exp_bc;

    // Discriminant D = sqrt(1 + 4*q2)
    let disc = (1.0 + 4.0 * q2).max(0.0);
    let d = disc.sqrt();
    let dd_dvbe = if d > 1e-15 { 2.0 * dq2_dvbe / d } else { 0.0 };
    let dd_dvbc = if d > 1e-15 { 2.0 * dq2_dvbc / d } else { 0.0 };

    // qb = q1 * (1 + D) / 2
    let qb = q1 * (1.0 + d) / 2.0;
    let dqb_dvbe = dq1_dvbe * (1.0 + d) / 2.0 + q1 * dd_dvbe / 2.0;
    let dqb_dvbc = dq1_dvbc * (1.0 + d) / 2.0 + q1 * dd_dvbc / 2.0;

    // Ic: transport current modulated by qb (ngspice bjtload.c:617)
    let ic = sign * (i_cc / qb - is / beta_r * (exp_bc - 1.0));
    // Ib: ideal forward + reverse, NOT divided by qb (ngspice bjtload.c:618)
    let ib = sign * (ib_fwd + ib_rev + ib_leak_be + ib_leak_bc);

    // Quotient rule for dIc: d(Icc/qb)/dV = (dIcc/dV * qb - Icc * dqb/dV) / qb^2
    let dicc_dvbe = is / nf_vt * exp_be;
    let dicc_dvbc = -is / nr_vt * exp_bc;
    let qb2 = (qb * qb).max(1e-30);
    let quotient_dvbe = (dicc_dvbe * qb - i_cc * dqb_dvbe) / qb2;
    let quotient_dvbc = (dicc_dvbc * qb - i_cc * dqb_dvbc) / qb2;
    let d_bc_term_dvbc = is / (beta_r * nr_vt) * exp_bc;

    // dIb Jacobian = pure Ebers-Moll (ngspice bjtload.c:627-628: gpi/gmu are
    // not modulated by qb — GP's modulation affects transport current only).
    (
        ic,
        ib,
        [
            quotient_dvbe,
            quotient_dvbc - d_bc_term_dvbc,
            dib_fwd_dvbe + dib_leak_dvbe,
            dib_rev_dvbc + dib_leak_dvbc,
        ],
    )
}

/// BJT with parasitic resistances (RB, RC, RE).
///
/// Given external junction voltages (Vbe_ext, Vbc_ext), solves for internal
/// junction voltages via inner 2D Newton-Raphson, then returns:
///   (Ic, Ib, [dIc/dVbe_ext, dIc/dVbc_ext, dIb/dVbe_ext, dIb/dVbc_ext])
///
/// The inner NR solves: find (Vbe_int, Vbc_int) such that
///   F1 = Vbe_int - Vbe_ext + Ib*RB + (Ic+Ib)*RE = 0
///   F2 = Vbc_int - Vbc_ext + Ib*RB - Ic*RC = 0
/// (note: RE term uses Ie = -(Ic+Ib), so V_E_int = V_E_ext - Ie*RE = V_E_ext + (Ic+Ib)*RE)
///
/// When RB=RC=RE=0, this reduces to direct evaluation (no inner loop).
#[inline(always)]
fn bjt_with_parasitics(
    vbe_ext: f64,
    vbc_ext: f64,
    is: f64,
    vt: f64,
    nf: f64,
    nr: f64,
    beta_f: f64,
    beta_r: f64,
    sign: f64,
    use_gp: bool,
    vaf: f64,
    var: f64,
    ikf: f64,
    ikr: f64,
    ise: f64,
    ne: f64,
    isc: f64,
    nc: f64,
    rb: f64,
    rc: f64,
    re: f64,
) -> (f64, f64, [f64; 4]) {
    const INNER_MAX_ITER: usize = 15;
    const INNER_TOL: f64 = 1e-10;

    // Initial guess: internal = external
    let mut vbe_int = vbe_ext;
    let mut vbc_int = vbc_ext;

    for _iter in 0..INNER_MAX_ITER {
        let (ic, ib, jac_int) = bjt_evaluate(
            vbe_int, vbc_int, is, vt, nf, nr, beta_f, beta_r, sign, use_gp, vaf, var, ikf, ikr,
            ise, ne, isc, nc,
        );
        let dic_dvbe = jac_int[0];
        let dic_dvbc = jac_int[1];
        let dib_dvbe = jac_int[2];
        let dib_dvbc = jac_int[3];

        // Residuals
        let f1 = vbe_int - vbe_ext + ib * rb + (ic + ib) * re;
        let f2 = vbc_int - vbc_ext + ib * rb - ic * rc;

        if f1.abs() < INNER_TOL && f2.abs() < INNER_TOL {
            break;
        }

        // Jacobian of F w.r.t. (Vbe_int, Vbc_int)
        let j11 = 1.0 + dib_dvbe * rb + (dic_dvbe + dib_dvbe) * re;
        let j12 = dib_dvbc * rb + (dic_dvbc + dib_dvbc) * re;
        let j21 = dib_dvbe * rb - dic_dvbe * rc;
        let j22 = 1.0 + dib_dvbc * rb - dic_dvbc * rc;

        // Solve 2x2 via Cramer's rule
        let det = j11 * j22 - j12 * j21;
        if det.abs() < 1e-30 {
            break;
        }
        let inv_det = 1.0 / det;
        let dvbe = (j22 * f1 - j12 * f2) * inv_det;
        let dvbc = (j11 * f2 - j21 * f1) * inv_det;

        // Step limiting: max ±4*VT per iteration
        let max_step = 4.0 * vt;
        let dvbe = dvbe.clamp(-max_step, max_step);
        let dvbc = dvbc.clamp(-max_step, max_step);

        vbe_int -= dvbe;
        vbc_int -= dvbc;
    }

    // Final evaluation at converged internal voltages
    let (ic, ib, jac_int) = bjt_evaluate(
        vbe_int, vbc_int, is, vt, nf, nr, beta_f, beta_r, sign, use_gp, vaf, var, ikf, ikr, ise,
        ne, isc, nc,
    );

    // External Jacobian: J_ext = J_device * J_F^{-1}
    // J_F = [[j11, j12], [j21, j22]] (recompute at converged point)
    let dic_dvbe = jac_int[0];
    let dic_dvbc = jac_int[1];
    let dib_dvbe = jac_int[2];
    let dib_dvbc = jac_int[3];

    let j11 = 1.0 + dib_dvbe * rb + (dic_dvbe + dib_dvbe) * re;
    let j12 = dib_dvbc * rb + (dic_dvbc + dib_dvbc) * re;
    let j21 = dib_dvbe * rb - dic_dvbe * rc;
    let j22 = 1.0 + dib_dvbc * rb - dic_dvbc * rc;

    let det = j11 * j22 - j12 * j21;
    if det.abs() < 1e-30 {
        // Fallback: return intrinsic Jacobian
        return (ic, ib, jac_int);
    }
    let inv_det = 1.0 / det;

    // J_F^{-1} = [[j22, -j12], [-j21, j11]] / det
    let fi11 = j22 * inv_det;
    let fi12 = -j12 * inv_det;
    let fi21 = -j21 * inv_det;
    let fi22 = j11 * inv_det;

    // J_ext = J_device * J_F^{-1}
    let dic_dvbe_ext = dic_dvbe * fi11 + dic_dvbc * fi21;
    let dic_dvbc_ext = dic_dvbe * fi12 + dic_dvbc * fi22;
    let dib_dvbe_ext = dib_dvbe * fi11 + dib_dvbc * fi21;
    let dib_dvbc_ext = dib_dvbe * fi12 + dib_dvbc * fi22;

    (
        ic,
        ib,
        [dic_dvbe_ext, dic_dvbc_ext, dib_dvbe_ext, dib_dvbc_ext],
    )
}

// =============================================================================
// STATE STRUCTURE (Nodal solver)
// =============================================================================

/// DC operating point: steady-state node voltages
pub const DC_OP: [f64; N] = [
    4.36625634132295470e0,
    0.00000000000000000e0,
    1.23603689217946333e0,
    2.80114566436168344e0,
    6.56905385625590865e-1,
    1.45000000000000000e1,
    1.34136800666353189e1,
    1.18746439971943616e1,
    -1.59752932827159078e-3,
];

/// DC operating point: nonlinear device currents at bias point
pub const DC_NL_I: [f64; M] = [
    7.50088406372789279e-5,
    4.83927999324380227e-7,
    1.51934555887281463e-3,
    9.80222940729557764e-6,
    1.59752930035797621e-3,
];

/// Circuit state for one processing channel (nodal solver).
///
/// Contains per-sample state and sample-rate-dependent matrices.
/// Call [`set_sample_rate`](CircuitState::set_sample_rate) before processing
/// if the host sample rate differs from [`SAMPLE_RATE`].
#[derive(Clone, Debug)]
pub struct CircuitState {
    /// Previous node voltages v[n-1]
    pub v_prev: [f64; N],

    /// Previous nonlinear currents i_nl[n-1]
    pub i_nl_prev: [f64; M],

    /// Nonlinear currents from two samples ago i_nl[n-2] (for NR predictor)
    pub i_nl_prev_prev: [f64; M],

    /// DC operating point (for reset/sleep/wake)
    pub dc_operating_point: [f64; N],

    /// Previous input sample for trapezoidal integration
    pub input_prev: f64,

    /// Previous `.inject` values (per inner sample), for the trapezoidal
    /// history term of Thevenin injections. Advanced once per inner call
    /// alongside `input_prev`.
    pub injections_prev: [f64; NUM_INJECT],

    /// NR convergence diagnostic from the last sample's solve.
    ///
    /// Semantics:
    /// - 0..MAX_ITER-1: 0-indexed iteration at which convergence was detected
    ///   (i.e. `last_nr_iterations + 1` iterations actually ran)
    /// - MAX_ITER: loop exhausted without convergence → NR failed
    ///
    /// The check `last_nr_iterations >= MAX_ITER` is the BE-fallback trigger;
    /// storing `iter` (not `iter + 1`) is intentional so that convergence at
    /// the final permitted iteration (iter == MAX_ITER - 1) does not false-trigger.
    pub last_nr_iterations: u32,

    /// Diagnostic: peak absolute output (pre-clamp)
    pub diag_peak_output: f64,
    /// Diagnostic: number of times output exceeded the ±output_clamp_v ceiling
    pub diag_clamp_count: u64,
    /// Diagnostic: number of times NR hit max iterations
    pub diag_nr_max_iter_count: u64,
    /// Diagnostic: device-samples where a pentode's grid conducts (Vgk > 0)
    /// or a BJT's base-collector junction is forward biased (saturation) —
    /// the regions the grid-off / forward-active reductions assume are never
    /// entered. Counted on the full models too (characterization, not a guard).
    pub diag_region_exit_count: u64,
    /// Diagnostic: number of backward Euler fallback activations
    pub diag_be_fallback_count: u64,
    /// Diagnostic: number of times the runtime BE-latch engaged (rising
    /// edges). Nonzero means the solver detected a self-sustaining Nyquist
    /// limit cycle on this stream and permanently switched that instance to
    /// the L-stable backward-Euler path (cleared by reset()). A plugin can
    /// surface this as "solver degraded". Always 0 on backward-Euler and
    /// force-trap builds.
    pub diag_be_latch_count: u64,
    /// Diagnostic: number of samples where the active-set rail resolve
    /// pinned at least one op-amp output (ActiveSet/ActiveSetBe only)
    pub diag_active_set_pin_count: u64,
    /// Diagnostic: number of times NaN triggered state reset
    pub diag_nan_reset_count: u64,
    /// Diagnostic: number of times a finite-but-implausible iterate
    /// (state magnitude beyond any physically-realizable circuit value)
    /// triggered state reset. NaN/Inf is caught by diag_nan_reset_count;
    /// this counts the "diverged but still is_finite()" gap.
    pub diag_magnitude_reset_count: u64,
    /// Diagnostic: number of samples that needed adaptive sub-stepping
    pub diag_substep_count: u64,
    /// Diagnostic: number of LU refactorizations performed
    pub diag_refactor_count: u64,
    /// Diagnostic: number of NR iterations whose Armijo line search was
    /// searched and failed (no `s` down to the 2^-10 floor met the
    /// sufficient-decrease test on a finite r0 > 1e-9). On such an
    /// iteration the loop takes the un-line-searched pnjlim/damp-limited
    /// step and continues; the always-checked residual gate still decides
    /// convergence. This is an expected event on stiff high-gain circuits,
    /// not an error — it is surfaced (not silenced) so the fall-through is
    /// observable. A non-finite or <=1e-9 r0 skips the search entirely and
    /// does NOT count here (ls_ok stays true).
    pub diag_ls_fail_count: u64,
    /// Diagnostic: number of samples hit by the global voltage-damping
    /// safety net. This is a legacy safeguard that scales v_new toward
    /// v_prev when any node moves more than ~2V (or 5% of max DC OP) in
    /// one sample. Per CLAUDE.md, output limiting must never mask solver
    /// bugs — treat a nonzero count here as a signal that the solver needs
    /// investigation, not as an acceptable steady-state.
    pub diag_voltage_damp_count: u64,

    // --- Cross-timestep chord method state (persisted LU factors) ---
    /// LU-factored Jacobian from previous convergence (chord method)
    pub chord_lu: [[f64; N]; N],
    /// Row equilibration scaling from LU factorization
    pub chord_dr: [f64; N],
    /// Column equilibration scaling from LU factorization
    pub chord_dc: [f64; N],
    /// Row permutation from LU factorization
    pub chord_perm: [usize; N],
    /// Device Jacobian consistent with chord_lu (for companion RHS)
    pub chord_j_dev: [f64; M * M],
    /// Whether chord LU factors are valid (false until first convergence)
    pub chord_valid: bool,
    /// Whether chord_lu holds DENSE (partial-pivoting) factors from the
    /// runtime fallback (sparse static pivoting rejected: tiny pivot or
    /// excessive element growth). Selects the matching back-solve.
    pub chord_dense: bool,

    /// A matrix: G + alpha*C (trapezoidal), recomputed by set_sample_rate
    pub a: [[f64; N]; N],
    /// A_neg matrix: alpha*C - G (trapezoidal history), recomputed by set_sample_rate
    pub a_neg: [[f64; N]; N],
    /// A_be matrix: G + (1/T)*C (backward Euler), recomputed by set_sample_rate
    pub a_be: [[f64; N]; N],
    /// A_neg_be matrix: (1/T)*C (backward Euler history), recomputed by set_sample_rate
    pub a_neg_be: [[f64; N]; N],
    /// S matrix: A^{-1} (trapezoidal), recomputed by set_sample_rate
    pub s: [[f64; N]; N],
    /// K matrix: N_v * S * N_i (nonlinear kernel), recomputed by set_sample_rate
    pub k: [[f64; M]; M],
    /// S_NI matrix: S * N_i (voltage recovery), recomputed by set_sample_rate
    pub s_ni: [[f64; M]; N],
    /// S_be matrix: A_be^{-1} (backward Euler), recomputed by set_sample_rate
    pub s_be: [[f64; N]; N],
    /// K_be matrix: N_v * S_be * N_i (BE kernel), recomputed by set_sample_rate
    pub k_be: [[f64; M]; M],
    /// S_NI_be matrix: S_be * N_i (BE voltage recovery), recomputed by set_sample_rate
    pub s_ni_be: [[f64; M]; N],
    /// S_sub matrix: (G+4C/T)^{-1} (trap at 2× rate), recomputed by set_sample_rate
    pub s_sub: [[f64; N]; N],
    /// A_neg_sub matrix: 4C/T-G (trap at 2× rate history), recomputed by set_sample_rate
    pub a_neg_sub: [[f64; N]; N],
    /// K_sub matrix: N_v*S_sub*N_i (sub-step kernel)
    pub k_sub: [[f64; M]; M],
    /// S_NI_sub matrix: S_sub*N_i (sub-step voltage recovery)
    pub s_ni_sub: [[f64; M]; N],

    // --- Runtime-adjustable device parameters ---
    /// Device 0 IS (Bjt) — runtime adjustable
    pub device_0_is: f64,
    /// Device 0 VT (Bjt) — runtime adjustable
    pub device_0_vt: f64,
    /// Device 0 BETA_F (Bjt) — runtime adjustable
    pub device_0_bf: f64,
    /// Device 0 BETA_R (Bjt) — runtime adjustable
    pub device_0_br: f64,
    /// Device 1 IS (Bjt) — runtime adjustable
    pub device_1_is: f64,
    /// Device 1 VT (Bjt) — runtime adjustable
    pub device_1_vt: f64,
    /// Device 1 BETA_F (Bjt) — runtime adjustable
    pub device_1_bf: f64,
    /// Device 1 BETA_R (Bjt) — runtime adjustable
    pub device_1_br: f64,
    /// Device 2 IS (Diode) — runtime adjustable
    pub device_2_is: f64,
    /// Device 2 N_VT (Diode) — runtime adjustable
    pub device_2_n_vt: f64,
}

impl Default for CircuitState {
    fn default() -> Self {
        let mut state = Self {
            v_prev: DC_OP,
            i_nl_prev: DC_NL_I,
            i_nl_prev_prev: DC_NL_I,
            dc_operating_point: DC_OP,
            input_prev: 0.0,
            injections_prev: [0.0; NUM_INJECT],
            last_nr_iterations: 0,
            diag_peak_output: 0.0,
            diag_clamp_count: 0,
            diag_nr_max_iter_count: 0,
            diag_region_exit_count: 0,
            diag_be_fallback_count: 0,
            diag_be_latch_count: 0,
            diag_active_set_pin_count: 0,
            diag_nan_reset_count: 0,
            diag_magnitude_reset_count: 0,
            diag_substep_count: 0,
            diag_refactor_count: 0,
            diag_ls_fail_count: 0,
            diag_voltage_damp_count: 0,
            chord_lu: [[0.0; N]; N],
            chord_dr: [1.0; N],
            chord_dc: [1.0; N],
            chord_perm: {
                {
                    let mut p = [0usize; N];
                    let mut i = 0;
                    while i < N {
                        p[i] = i;
                        i += 1;
                    }
                    p
                }
            },
            chord_j_dev: [0.0; M * M],
            chord_valid: false,
            chord_dense: false,
            a: A_DEFAULT,
            a_neg: A_NEG_DEFAULT,
            a_be: A_BE_DEFAULT,
            a_neg_be: A_NEG_BE_DEFAULT,
            s: S_DEFAULT,
            k: K_DEFAULT,
            s_ni: S_NI_DEFAULT,
            s_be: S_BE_DEFAULT,
            s_sub: S_SUB_DEFAULT,
            a_neg_sub: A_NEG_SUB_DEFAULT,
            k_sub: K_SUB_DEFAULT,
            s_ni_sub: S_NI_SUB_DEFAULT,
            k_be: K_BE_DEFAULT,
            s_ni_be: S_NI_BE_DEFAULT,
            device_0_is: DEVICE_0_IS,
            device_0_vt: DEVICE_0_VT,
            device_0_bf: DEVICE_0_BETA_F,
            device_0_br: DEVICE_0_BETA_R,
            device_1_is: DEVICE_1_IS,
            device_1_vt: DEVICE_1_VT,
            device_1_bf: DEVICE_1_BETA_F,
            device_1_br: DEVICE_1_BETA_R,
            device_2_is: DEVICE_2_IS,
            device_2_n_vt: DEVICE_2_N_VT,
        };
        state.warmup();
        state
    }
}

impl CircuitState {
    /// Reset to DC operating point
    pub fn reset(&mut self) {
        self.v_prev = self.dc_operating_point;
        self.i_nl_prev = DC_NL_I;
        self.i_nl_prev_prev = DC_NL_I;
        self.input_prev = 0.0;
        self.injections_prev = [0.0; NUM_INJECT];
        self.last_nr_iterations = 0;
        self.chord_valid = false;
        self.diag_peak_output = 0.0;
        self.diag_clamp_count = 0;
        self.diag_nr_max_iter_count = 0;
        self.diag_region_exit_count = 0;
        self.diag_be_fallback_count = 0;
        self.diag_be_latch_count = 0;
        self.diag_active_set_pin_count = 0;
        self.diag_nan_reset_count = 0;
        self.diag_magnitude_reset_count = 0;
        self.diag_voltage_damp_count = 0;
        self.diag_substep_count = 0;
        self.diag_refactor_count = 0;
        self.diag_ls_fail_count = 0;
        self.device_0_is = DEVICE_0_IS;
        self.device_0_vt = DEVICE_0_VT;
        self.device_0_bf = DEVICE_0_BETA_F;
        self.device_0_br = DEVICE_0_BETA_R;
        self.device_1_is = DEVICE_1_IS;
        self.device_1_vt = DEVICE_1_VT;
        self.device_1_bf = DEVICE_1_BETA_F;
        self.device_1_br = DEVICE_1_BETA_R;
        self.device_2_is = DEVICE_2_IS;
        self.device_2_n_vt = DEVICE_2_N_VT;
        self.a = A_DEFAULT;
        self.a_neg = A_NEG_DEFAULT;
        self.a_be = A_BE_DEFAULT;
        self.a_neg_be = A_NEG_BE_DEFAULT;
        self.s = S_DEFAULT;
        self.k = K_DEFAULT;
        self.s_ni = S_NI_DEFAULT;
        self.s_be = S_BE_DEFAULT;
        self.k_be = K_BE_DEFAULT;
        self.s_ni_be = S_NI_BE_DEFAULT;
        self.s_sub = S_SUB_DEFAULT;
        self.a_neg_sub = A_NEG_SUB_DEFAULT;
        self.k_sub = K_SUB_DEFAULT;
        self.s_ni_sub = S_NI_SUB_DEFAULT;
        self.warmup();
    }

    /// Run silent warmup samples to settle into the correct operating point.
    ///
    /// Call after construction or reset() to ensure the circuit settles into
    /// the physically correct basin of attraction. Without warmup, circuits
    /// with high-gain op-amps may lock into a parasitic equilibrium.
    ///
    /// The default `CircuitState::default()` calls this automatically.
    pub fn warmup(&mut self) {
        for _ in 0..50 {
            process_sample(0.0, &[[0.0; NUM_INJECT]; OVERSAMPLING_FACTOR], self);
        }
    }

    /// Set DC operating point (call after DC analysis)
    pub fn set_dc_operating_point(&mut self, v_dc: [f64; N]) {
        self.dc_operating_point = v_dc;
        self.v_prev = v_dc;
    }

    /// Read the baked DC operating point for this circuit.
    ///
    /// Solution to the nonlinear DC system computed at codegen time (at nominal
    /// pot/switch values) and frozen into `DC_OP`. Prefer this over `v_prev` when
    /// you want the *designed* bias point — `v_prev` carries per-sample dynamics.
    #[inline]
    pub fn dc_op(&self) -> &[f64; N] {
        &self.dc_operating_point
    }

    /// Pretty-print the DC operating point with user-assigned node names.
    ///
    /// Writes one line per named node to `stderr`. Intended for plugin
    /// bring-up diagnostics, not the audio thread (formatting allocates).
    pub fn dc_op_dump(&self) {
        let dc = &self.dc_operating_point;
        eprintln!("  V(OUT) = {:+.4} V", dc[0]);
        eprintln!("  V(NODE_HP) = {:+.4} V", dc[1]);
        eprintln!("  V(BASE3) = {:+.4} V", dc[2]);
        eprintln!("  V(NODE_LP) = {:+.4} V", dc[3]);
        eprintln!("  V(EMIT3) = {:+.4} V", dc[4]);
        eprintln!("  V(VCC) = {:+.4} V", dc[5]);
        eprintln!("  V(LEDA) = {:+.4} V", dc[6]);
        eprintln!("  V(LEDK) = {:+.4} V", dc[7]);
    }

    /// Recompute all sample-rate-dependent matrices for a new sample rate.
    ///
    /// Call this once during plugin initialization (NOT on the audio thread).
    /// Rebuilds A, A_neg, A_be, A_neg_be from stored G and C matrices.
    pub fn set_sample_rate(&mut self, sample_rate: f64) {
        if !(sample_rate > 0.0 && sample_rate.is_finite()) {
            return;
        }

        // If same as codegen sample rate, reset to defaults
        if (sample_rate - SAMPLE_RATE).abs() < 0.5 {
            self.a = A_DEFAULT;
            self.a_neg = A_NEG_DEFAULT;
            self.a_be = A_BE_DEFAULT;
            self.a_neg_be = A_NEG_BE_DEFAULT;
            self.s = S_DEFAULT;
            self.s_be = S_BE_DEFAULT;
            self.k = K_DEFAULT;
            self.s_ni = S_NI_DEFAULT;
            self.k_be = K_BE_DEFAULT;
            self.s_ni_be = S_NI_BE_DEFAULT;
            self.s_sub = S_SUB_DEFAULT;
            self.a_neg_sub = A_NEG_SUB_DEFAULT;
            self.k_sub = K_SUB_DEFAULT;
            self.s_ni_sub = S_NI_SUB_DEFAULT;
            // POLICY: transient state — oversampler filter history,
            // DC-blocker history, solver v_prev/i_nl history — is
            // PRESERVED here. Only coefficients and matrices are
            // restored: a same-rate call is a no-op reconfiguration
            // and must not click (DK-template parity).
            return;
        }

        let internal_rate = sample_rate * 1.0;
        self.rebuild_matrices(internal_rate);
    }

    /// Recompute A, A_neg, A_be, A_neg_be from G and C.
    ///
    /// Called by set_sample_rate, set_pot, and set_switch.
    /// Also recomputes the Schur matrices S, K, S_NI (and BE variants),
    /// which includes O(N^3) matrix inversion.
    pub fn rebuild_matrices(&mut self, internal_rate: f64) {
        let alpha = internal_rate; // backward Euler: alpha = 1/T
        let alpha_be = internal_rate;
        let alpha_sub = 4.0 * internal_rate; // trap at 2× rate

        for i in 0..N {
            for j in 0..N {
                self.a[i][j] = G[i][j] + alpha * C[i][j];
                self.a_neg[i][j] = alpha * C[i][j];
                self.a_be[i][j] = G[i][j] + alpha_be * C[i][j];
                self.a_neg_be[i][j] = alpha_be * C[i][j];
            }
        }
        for i in 0..N {
            for j in 0..N {
                self.a_neg_sub[i][j] = alpha_sub * C[i][j] - G[i][j];
            }
        }
        for i in 8..9 {
            for j in 0..N {
                self.a_neg[i][j] = 0.0;
                self.a_neg_be[i][j] = 0.0;
            }
        }
        for i in 8..9 {
            for j in 0..N {
                self.a_neg_sub[i][j] = 0.0;
            }
        }

        // Recompute S = A^{-1} (trapezoidal)
        if let Some(inv) = invert_n(&self.a) {
            self.s = inv;
            // S_NI = S * N_i
            for i in 0..N {
                for j in 0..M {
                    let mut sum = 0.0;
                    for a in 0..N {
                        sum += self.s[i][a] * N_I[a][j];
                    }
                    self.s_ni[i][j] = sum;
                }
            }
            // K = N_v * S_NI
            for i in 0..M {
                for j in 0..M {
                    let mut sum = 0.0;
                    for a in 0..N {
                        sum += N_V[i][a] * self.s_ni[a][j];
                    }
                    self.k[i][j] = sum;
                }
            }
        }
        // Recompute S_be = A_be^{-1} (backward Euler)
        if let Some(inv) = invert_n(&self.a_be) {
            self.s_be = inv;
            // S_NI = S * N_i
            for i in 0..N {
                for j in 0..M {
                    let mut sum = 0.0;
                    for a in 0..N {
                        sum += self.s_be[i][a] * N_I[a][j];
                    }
                    self.s_ni_be[i][j] = sum;
                }
            }
            // K = N_v * S_NI
            for i in 0..M {
                for j in 0..M {
                    let mut sum = 0.0;
                    for a in 0..N {
                        sum += N_V[i][a] * self.s_ni_be[a][j];
                    }
                    self.k_be[i][j] = sum;
                }
            }
        }

        // Invalidate chord LU cache (matrices changed)
        self.chord_valid = false;
    }
}

// =============================================================================
// MATRIX INVERSION (for rebuild_matrices)
// =============================================================================

/// Invert an N×N matrix via LU factorization with partial pivoting.
/// Returns None if the matrix is singular (pivot < 1e-30).
///
/// Called three times per `rebuild_matrices` on the nodal path
/// (S = A^-1, S_be = A_be^-1, S_sub = A_sub^-1), so factor-then-
/// solve uses ~half the work of the prior Gauss-Jordan on an
/// augmented [A | I] matrix and halves the stack footprint.
#[inline(never)]
fn invert_n(a: &[[f64; N]; N]) -> Option<[[f64; N]; N]> {
    let mut lu = *a;
    let mut perm = [0usize; N];
    for i in 0..N {
        perm[i] = i;
    }

    for k in 0..N {
        let mut max_row = k;
        let mut max_val = lu[k][k].abs();
        for i in (k + 1)..N {
            let v = lu[i][k].abs();
            if v > max_val {
                max_val = v;
                max_row = i;
            }
        }
        if max_val < 1e-30 {
            return None;
        }
        if max_row != k {
            lu.swap(k, max_row);
            perm.swap(k, max_row);
        }
        let pivot = lu[k][k];
        for i in (k + 1)..N {
            let m = lu[i][k] / pivot;
            lu[i][k] = m;
            for j in (k + 1)..N {
                lu[i][j] -= m * lu[k][j];
            }
        }
    }

    let mut result = [[0.0f64; N]; N];
    for col in 0..N {
        let mut b = [0.0f64; N];
        let mut start = N;
        for i in 0..N {
            if perm[i] == col {
                b[i] = 1.0;
                start = i;
                break;
            }
        }
        for i in (start + 1)..N {
            let mut sum = b[i];
            for j in start..i {
                sum -= lu[i][j] * b[j];
            }
            b[i] = sum;
        }
        for i in (0..N).rev() {
            let mut sum = b[i];
            for j in (i + 1)..N {
                sum -= lu[i][j] * b[j];
            }
            let pivot = lu[i][i];
            if pivot.abs() < 1e-30 {
                return None;
            }
            b[i] = sum / pivot;
        }
        for i in 0..N {
            result[i][col] = b[i];
        }
    }

    Some(result)
}

// =============================================================================
// PROCESS SAMPLE (Schur complement: M-dim NR via precomputed S = A^{-1})
// =============================================================================

/// Process a single sample at the internal (oversampled) rate.
///
/// Called by `process_sample()` through the oversampling chain.
#[inline(always)]
fn process_sample_inner(
    input: f64,
    injections: [f64; NUM_INJECT],
    state: &mut CircuitState,
) -> ([f64; NUM_OUTPUTS], [f64; NUM_TAP]) {
    let input = if input.is_finite() {
        input.clamp(-100.0, 100.0)
    } else {
        0.0
    };

    // Sanitize injections (NaN/Inf → 0). No magnitude clamp: a feedback value
    // is arbitrary and the plausibility guard catches any runaway.
    let mut injections = injections;
    for v in injections.iter_mut() {
        *v = if v.is_finite() { *v } else { 0.0 };
    }

    for v in state.v_prev.iter_mut() {
        *v = *v + 1e-25 - 1e-25;
    }
    for v in state.i_nl_prev.iter_mut() {
        *v = *v + 1e-25 - 1e-25;
    }

    // Step 1: Build RHS (sparse A_neg * v_prev + sparse N_i * i_nl_prev)
    let mut rhs = RHS_CONST;
    rhs[0] += state.a_neg[0][0] * state.v_prev[0];
    rhs[0] += state.a_neg[0][1] * state.v_prev[1];
    rhs[1] += state.a_neg[1][0] * state.v_prev[0];
    rhs[1] += state.a_neg[1][1] * state.v_prev[1];
    rhs[1] += state.a_neg[1][2] * state.v_prev[2];
    rhs[2] += state.a_neg[2][1] * state.v_prev[1];
    rhs[2] += state.a_neg[2][2] * state.v_prev[2];
    rhs[3] += state.a_neg[3][3] * state.v_prev[3];

    let input_conductance = 1.0 / INPUT_RESISTANCE;
    // Input source (backward Euler: V_in * G_in)
    rhs[INPUT_NODE] += input * input_conductance;

    // Step 2: Linear prediction v_pred = S * rhs (O(N^2))
    let mut v_pred = [0.0f64; N];
    for i in 0..N {
        let mut sum = 0.0;
        for j in 0..N {
            sum += state.s[i][j] * rhs[j];
        }
        v_pred[i] = sum;
    }

    // Step 3: Extract device voltages p = N_v * v_pred (sparse)
    let mut p = [0.0f64; M];
    p[0] = N_V[0][2] * v_pred[2] + N_V[0][4] * v_pred[4];
    p[1] = N_V[1][0] * v_pred[0] + N_V[1][2] * v_pred[2];
    p[2] = N_V[2][4] * v_pred[4];
    p[3] = N_V[3][0] * v_pred[0] + N_V[3][4] * v_pred[4];
    p[4] = N_V[4][6] * v_pred[6] + N_V[4][7] * v_pred[7];

    // Step 4: M-dim Newton-Raphson (Schur complement)
    // First-order predictor warm start
    let mut i_nl = [0.0f64; M];
    for i in 0..M {
        i_nl[i] = 2.0 * state.i_nl_prev[i] - state.i_nl_prev_prev[i];
    }
    state.last_nr_iterations = MAX_ITER as u32;

    for iter in 0..MAX_ITER {
        // 4a. Compute controlling voltages: v_d = p + K * i_nl
        let v_d0 = p[0]
            + state.k[0][0] * i_nl[0]
            + state.k[0][1] * i_nl[1]
            + state.k[0][2] * i_nl[2]
            + state.k[0][3] * i_nl[3]
            + state.k[0][4] * i_nl[4];
        let v_d1 = p[1]
            + state.k[1][0] * i_nl[0]
            + state.k[1][1] * i_nl[1]
            + state.k[1][2] * i_nl[2]
            + state.k[1][4] * i_nl[4];
        let v_d2 =
            p[2] + state.k[2][0] * i_nl[0] + state.k[2][1] * i_nl[1] + state.k[2][3] * i_nl[3];
        let v_d3 = p[3]
            + state.k[3][0] * i_nl[0]
            + state.k[3][1] * i_nl[1]
            + state.k[3][2] * i_nl[2]
            + state.k[3][3] * i_nl[3]
            + state.k[3][4] * i_nl[4];
        let v_d4 = p[4]
            + state.k[4][0] * i_nl[0]
            + state.k[4][1] * i_nl[1]
            + state.k[4][2] * i_nl[2]
            + state.k[4][4] * i_nl[4];

        // 4b. Evaluate device currents and Jacobians
        let (i_dev0, i_dev1, bjt0_jac) = bjt_evaluate(
            v_d0,
            v_d1,
            state.device_0_is,
            state.device_0_vt,
            DEVICE_0_NF,
            DEVICE_0_NR,
            state.device_0_bf,
            state.device_0_br,
            DEVICE_0_SIGN,
            DEVICE_0_USE_GP,
            DEVICE_0_VAF,
            DEVICE_0_VAR,
            DEVICE_0_IKF,
            DEVICE_0_IKR,
            DEVICE_0_ISE,
            DEVICE_0_NE,
            DEVICE_0_ISC,
            DEVICE_0_NC,
        );
        let jdev_0_0 = bjt0_jac[0];
        let jdev_0_1 = bjt0_jac[1];
        let jdev_1_0 = bjt0_jac[2];
        let jdev_1_1 = bjt0_jac[3];
        let (i_dev2, i_dev3, bjt1_jac) = bjt_evaluate(
            v_d2,
            v_d3,
            state.device_1_is,
            state.device_1_vt,
            DEVICE_1_NF,
            DEVICE_1_NR,
            state.device_1_bf,
            state.device_1_br,
            DEVICE_1_SIGN,
            DEVICE_1_USE_GP,
            DEVICE_1_VAF,
            DEVICE_1_VAR,
            DEVICE_1_IKF,
            DEVICE_1_IKR,
            DEVICE_1_ISE,
            DEVICE_1_NE,
            DEVICE_1_ISC,
            DEVICE_1_NC,
        );
        let jdev_2_2 = bjt1_jac[0];
        let jdev_2_3 = bjt1_jac[1];
        let jdev_3_2 = bjt1_jac[2];
        let jdev_3_3 = bjt1_jac[3];
        let i_dev4 = diode_current(v_d4, state.device_2_is, state.device_2_n_vt);
        let jdev_4_4 = diode_conductance(v_d4, state.device_2_is, state.device_2_n_vt);

        // 4c. Residuals: f(i) = i_nl - i_dev = 0
        let f0 = i_nl[0] - i_dev0;
        let f1 = i_nl[1] - i_dev1;
        let f2 = i_nl[2] - i_dev2;
        let f3 = i_nl[3] - i_dev3;
        let f4 = i_nl[4] - i_dev4;

        // 4d. Jacobian: J[i][j] = delta_ij - jdev * K
        let j0_0 = 1.0 - jdev_0_0 * state.k[0][0] - jdev_0_1 * state.k[1][0];
        let j0_1 = 0.0 - jdev_0_0 * state.k[0][1] - jdev_0_1 * state.k[1][1];
        let j0_2 = 0.0 - jdev_0_0 * state.k[0][2] - jdev_0_1 * state.k[1][2];
        let j0_3 = 0.0 - jdev_0_0 * state.k[0][3] - jdev_0_1 * state.k[1][3];
        let j0_4 = 0.0 - jdev_0_0 * state.k[0][4] - jdev_0_1 * state.k[1][4];
        let j1_0 = 0.0 - jdev_1_0 * state.k[0][0] - jdev_1_1 * state.k[1][0];
        let j1_1 = 1.0 - jdev_1_0 * state.k[0][1] - jdev_1_1 * state.k[1][1];
        let j1_2 = 0.0 - jdev_1_0 * state.k[0][2] - jdev_1_1 * state.k[1][2];
        let j1_3 = 0.0 - jdev_1_0 * state.k[0][3] - jdev_1_1 * state.k[1][3];
        let j1_4 = 0.0 - jdev_1_0 * state.k[0][4] - jdev_1_1 * state.k[1][4];
        let j2_0 = 0.0 - jdev_2_2 * state.k[2][0] - jdev_2_3 * state.k[3][0];
        let j2_1 = 0.0 - jdev_2_2 * state.k[2][1] - jdev_2_3 * state.k[3][1];
        let j2_2 = 1.0 - jdev_2_2 * state.k[2][2] - jdev_2_3 * state.k[3][2];
        let j2_3 = 0.0 - jdev_2_2 * state.k[2][3] - jdev_2_3 * state.k[3][3];
        let j2_4 = 0.0 - jdev_2_2 * state.k[2][4] - jdev_2_3 * state.k[3][4];
        let j3_0 = 0.0 - jdev_3_2 * state.k[2][0] - jdev_3_3 * state.k[3][0];
        let j3_1 = 0.0 - jdev_3_2 * state.k[2][1] - jdev_3_3 * state.k[3][1];
        let j3_2 = 0.0 - jdev_3_2 * state.k[2][2] - jdev_3_3 * state.k[3][2];
        let j3_3 = 1.0 - jdev_3_2 * state.k[2][3] - jdev_3_3 * state.k[3][3];
        let j3_4 = 0.0 - jdev_3_2 * state.k[2][4] - jdev_3_3 * state.k[3][4];
        let j4_0 = 0.0 - jdev_4_4 * state.k[4][0];
        let j4_1 = 0.0 - jdev_4_4 * state.k[4][1];
        let j4_2 = 0.0 - jdev_4_4 * state.k[4][2];
        let j4_3 = 0.0 - jdev_4_4 * state.k[4][3];
        let j4_4 = 1.0 - jdev_4_4 * state.k[4][4];

        // Solve 5x5 system via inline Gaussian elimination
        let mut a = [
            [j0_0, j0_1, j0_2, j0_3, j0_4],
            [j1_0, j1_1, j1_2, j1_3, j1_4],
            [j2_0, j2_1, j2_2, j2_3, j2_4],
            [j3_0, j3_1, j3_2, j3_3, j3_4],
            [j4_0, j4_1, j4_2, j4_3, j4_4],
        ];
        let mut b = [f0, f1, f2, f3, f4];
        let mut singular = false;
        for col in 0..5 {
            let mut max_row = col;
            let mut max_val = a[col][col].abs();
            for row in (col + 1)..5 {
                if a[row][col].abs() > max_val {
                    max_val = a[row][col].abs();
                    max_row = row;
                }
            }
            if max_val < 1e-15 {
                singular = true;
                break;
            }
            if max_row != col {
                a.swap(col, max_row);
                b.swap(col, max_row);
            }
            let pivot = a[col][col];
            for row in (col + 1)..5 {
                let factor = a[row][col] / pivot;
                for j in (col + 1)..5 {
                    a[row][j] -= factor * a[col][j];
                }
                b[row] -= factor * b[col];
            }
        }
        if !singular {
            for i in (0..5).rev() {
                let mut sum = b[i];
                for j in (i + 1)..5 {
                    sum -= a[i][j] * b[j];
                }
                if a[i][i].abs() < 1e-15 {
                    singular = true;
                    break;
                }
                b[i] = sum / a[i][i];
            }
        }
        if !singular {
            let delta0 = b[0];
            let delta1 = b[1];
            let delta2 = b[2];
            let delta3 = b[3];
            let delta4 = b[4];
            // Trial voltages: apply full NR step, then limit
            let i_trial0 = i_nl[0] - delta0;
            let i_trial1 = i_nl[1] - delta1;
            let i_trial2 = i_nl[2] - delta2;
            let i_trial3 = i_nl[3] - delta3;
            let i_trial4 = i_nl[4] - delta4;
            let v_trial0 = p[0]
                + state.k[0][0] * i_trial0
                + state.k[0][1] * i_trial1
                + state.k[0][2] * i_trial2
                + state.k[0][3] * i_trial3
                + state.k[0][4] * i_trial4;
            let v_trial1 = p[1]
                + state.k[1][0] * i_trial0
                + state.k[1][1] * i_trial1
                + state.k[1][2] * i_trial2
                + state.k[1][3] * i_trial3
                + state.k[1][4] * i_trial4;
            let v_trial2 = p[2]
                + state.k[2][0] * i_trial0
                + state.k[2][1] * i_trial1
                + state.k[2][2] * i_trial2
                + state.k[2][3] * i_trial3
                + state.k[2][4] * i_trial4;
            let v_trial3 = p[3]
                + state.k[3][0] * i_trial0
                + state.k[3][1] * i_trial1
                + state.k[3][2] * i_trial2
                + state.k[3][3] * i_trial3
                + state.k[3][4] * i_trial4;
            let v_trial4 = p[4]
                + state.k[4][0] * i_trial0
                + state.k[4][1] * i_trial1
                + state.k[4][2] * i_trial2
                + state.k[4][3] * i_trial3
                + state.k[4][4] * i_trial4;
            let mut any_limited = false;
            let dv_trial0 = v_trial0 - v_d0;
            let v_lim0 = if dv_trial0.abs() > 1e-4 {
                pnjlim(v_trial0, v_d0, state.device_0_vt, DEVICE_0_VCRIT)
            } else {
                v_trial0
            };
            let dv_trial1 = v_trial1 - v_d1;
            let v_lim1 = if dv_trial1.abs() > 1e-4 {
                pnjlim(v_trial1, v_d1, state.device_0_vt, DEVICE_0_VCRIT)
            } else {
                v_trial1
            };
            let dv_trial2 = v_trial2 - v_d2;
            let v_lim2 = if dv_trial2.abs() > 1e-4 {
                pnjlim(v_trial2, v_d2, state.device_1_vt, DEVICE_1_VCRIT)
            } else {
                v_trial2
            };
            let dv_trial3 = v_trial3 - v_d3;
            let v_lim3 = if dv_trial3.abs() > 1e-4 {
                pnjlim(v_trial3, v_d3, state.device_1_vt, DEVICE_1_VCRIT)
            } else {
                v_trial3
            };
            let dv_trial4 = v_trial4 - v_d4;
            let v_lim4 = if dv_trial4.abs() > 1e-4 {
                pnjlim(v_trial4, v_d4, state.device_2_n_vt, DEVICE_2_VCRIT)
            } else {
                v_trial4
            };
            let mut global_alpha = 1.0_f64;
            {
                let dv_lim = v_lim0 - v_d0;
                if dv_trial0.abs() > 1e-15 {
                    let r = if dv_trial0 * dv_lim < 0.0 {
                        0.0
                    } else {
                        (dv_lim / dv_trial0).clamp(0.0, 1.0)
                    };
                    if r < global_alpha {
                        global_alpha = r;
                        any_limited = true;
                    }
                }
            }
            {
                let dv_lim = v_lim1 - v_d1;
                if dv_trial1.abs() > 1e-15 {
                    let r = if dv_trial1 * dv_lim < 0.0 {
                        0.0
                    } else {
                        (dv_lim / dv_trial1).clamp(0.0, 1.0)
                    };
                    if r < global_alpha {
                        global_alpha = r;
                        any_limited = true;
                    }
                }
            }
            {
                let dv_lim = v_lim2 - v_d2;
                if dv_trial2.abs() > 1e-15 {
                    let r = if dv_trial2 * dv_lim < 0.0 {
                        0.0
                    } else {
                        (dv_lim / dv_trial2).clamp(0.0, 1.0)
                    };
                    if r < global_alpha {
                        global_alpha = r;
                        any_limited = true;
                    }
                }
            }
            {
                let dv_lim = v_lim3 - v_d3;
                if dv_trial3.abs() > 1e-15 {
                    let r = if dv_trial3 * dv_lim < 0.0 {
                        0.0
                    } else {
                        (dv_lim / dv_trial3).clamp(0.0, 1.0)
                    };
                    if r < global_alpha {
                        global_alpha = r;
                        any_limited = true;
                    }
                }
            }
            {
                let dv_lim = v_lim4 - v_d4;
                if dv_trial4.abs() > 1e-15 {
                    let r = if dv_trial4 * dv_lim < 0.0 {
                        0.0
                    } else {
                        (dv_lim / dv_trial4).clamp(0.0, 1.0)
                    };
                    if r < global_alpha {
                        global_alpha = r;
                        any_limited = true;
                    }
                }
            }
            {
                let max_dv = (dv_trial0 * global_alpha)
                    .abs()
                    .max((dv_trial1 * global_alpha).abs())
                    .max((dv_trial2 * global_alpha).abs())
                    .max((dv_trial3 * global_alpha).abs())
                    .max((dv_trial4 * global_alpha).abs());
                if max_dv > 3.500000 {
                    global_alpha *= 3.500000 / max_dv;
                    any_limited = true;
                }
            }
            i_nl[0] -= global_alpha * delta0;
            i_nl[1] -= global_alpha * delta1;
            i_nl[2] -= global_alpha * delta2;
            i_nl[3] -= global_alpha * delta3;
            i_nl[4] -= global_alpha * delta4;

            // Convergence check (SPICE RELTOL=0.001, VNTOL=1e-6)
            if !any_limited {
                let mut nr_converged = true;
                {
                    let dv = dv_trial0 * global_alpha;
                    let threshold = 1e-3 * v_d0.abs().max((v_d0 + dv).abs()) + 1e-6;
                    if !(dv.abs() <= threshold) {
                        nr_converged = false;
                    }
                }
                {
                    let dv = dv_trial1 * global_alpha;
                    let threshold = 1e-3 * v_d1.abs().max((v_d1 + dv).abs()) + 1e-6;
                    if !(dv.abs() <= threshold) {
                        nr_converged = false;
                    }
                }
                {
                    let dv = dv_trial2 * global_alpha;
                    let threshold = 1e-3 * v_d2.abs().max((v_d2 + dv).abs()) + 1e-6;
                    if !(dv.abs() <= threshold) {
                        nr_converged = false;
                    }
                }
                {
                    let dv = dv_trial3 * global_alpha;
                    let threshold = 1e-3 * v_d3.abs().max((v_d3 + dv).abs()) + 1e-6;
                    if !(dv.abs() <= threshold) {
                        nr_converged = false;
                    }
                }
                {
                    let dv = dv_trial4 * global_alpha;
                    let threshold = 1e-3 * v_d4.abs().max((v_d4 + dv).abs()) + 1e-6;
                    if !(dv.abs() <= threshold) {
                        nr_converged = false;
                    }
                }
                if nr_converged {
                    state.last_nr_iterations = iter as u32;
                    break;
                }
            }
        } else {
            // Singular Jacobian — damped fallback (0.5 * residual, adaptive clamp)
            {
                let clamp = (i_nl[0].abs() * 0.1).max(0.01);
                i_nl[0] -= (f0 * 0.5).clamp(-clamp, clamp);
            }
            {
                let clamp = (i_nl[1].abs() * 0.1).max(0.01);
                i_nl[1] -= (f1 * 0.5).clamp(-clamp, clamp);
            }
            {
                let clamp = (i_nl[2].abs() * 0.1).max(0.01);
                i_nl[2] -= (f2 * 0.5).clamp(-clamp, clamp);
            }
            {
                let clamp = (i_nl[3].abs() * 0.1).max(0.01);
                i_nl[3] -= (f3 * 0.5).clamp(-clamp, clamp);
            }
            {
                let clamp = (i_nl[4].abs() * 0.1).max(0.01);
                i_nl[4] -= (f4 * 0.5).clamp(-clamp, clamp);
            }
        }
    }

    // Step 5: Recover full node voltages: v = v_pred + S_NI * i_nl
    let mut v = v_pred;
    for i in 0..N {
        for j in 0..M {
            v[i] += state.s_ni[i][j] * i_nl[j];
        }
    }
    let converged = state.last_nr_iterations < MAX_ITER as u32;

    // Backward Euler fallback
    if !converged {
        if state.last_nr_iterations >= MAX_ITER as u32 {
            state.diag_nr_max_iter_count += 1;
        }
        state.diag_be_fallback_count += 1;

        // Rebuild RHS with backward Euler matrices
        let mut rhs_be = [0.0f64; N];
        for i in 0..N {
            let mut sum = RHS_CONST_BE[i];
            for j in 0..N {
                sum += state.a_neg_be[i][j] * state.v_prev[j];
            }
            rhs_be[i] = sum;
        }
        rhs_be[INPUT_NODE] += input * input_conductance;

        // BE linear prediction: v_pred_be = S_be * rhs_be
        let mut v_pred_be = [0.0f64; N];
        for i in 0..N {
            let mut sum = 0.0;
            for j in 0..N {
                sum += state.s_be[i][j] * rhs_be[j];
            }
            v_pred_be[i] = sum;
        }

        let mut p_be = [0.0f64; M];
        for i in 0..M {
            let mut sum = 0.0;
            for j in 0..N {
                sum += N_V[i][j] * v_pred_be[j];
            }
            p_be[i] = sum;
        }

        // Reset i_nl to predictor for BE attempt
        for i in 0..M {
            i_nl[i] = 2.0 * state.i_nl_prev[i] - state.i_nl_prev_prev[i];
        }

        for _iter in 0..MAX_ITER {
            let v_d0 = p_be[0]
                + state.k_be[0][0] * i_nl[0]
                + state.k_be[0][1] * i_nl[1]
                + state.k_be[0][2] * i_nl[2]
                + state.k_be[0][3] * i_nl[3]
                + state.k_be[0][4] * i_nl[4];
            let v_d1 = p_be[1]
                + state.k_be[1][0] * i_nl[0]
                + state.k_be[1][1] * i_nl[1]
                + state.k_be[1][2] * i_nl[2]
                + state.k_be[1][3] * i_nl[3]
                + state.k_be[1][4] * i_nl[4];
            let v_d2 = p_be[2]
                + state.k_be[2][0] * i_nl[0]
                + state.k_be[2][1] * i_nl[1]
                + state.k_be[2][2] * i_nl[2]
                + state.k_be[2][3] * i_nl[3]
                + state.k_be[2][4] * i_nl[4];
            let v_d3 = p_be[3]
                + state.k_be[3][0] * i_nl[0]
                + state.k_be[3][1] * i_nl[1]
                + state.k_be[3][2] * i_nl[2]
                + state.k_be[3][3] * i_nl[3]
                + state.k_be[3][4] * i_nl[4];
            let v_d4 = p_be[4]
                + state.k_be[4][0] * i_nl[0]
                + state.k_be[4][1] * i_nl[1]
                + state.k_be[4][2] * i_nl[2]
                + state.k_be[4][3] * i_nl[3]
                + state.k_be[4][4] * i_nl[4];

            let (i_dev0, i_dev1, bjt0_jac) = bjt_evaluate(
                v_d0,
                v_d1,
                state.device_0_is,
                state.device_0_vt,
                DEVICE_0_NF,
                DEVICE_0_NR,
                state.device_0_bf,
                state.device_0_br,
                DEVICE_0_SIGN,
                DEVICE_0_USE_GP,
                DEVICE_0_VAF,
                DEVICE_0_VAR,
                DEVICE_0_IKF,
                DEVICE_0_IKR,
                DEVICE_0_ISE,
                DEVICE_0_NE,
                DEVICE_0_ISC,
                DEVICE_0_NC,
            );
            let jdev_0_0 = bjt0_jac[0];
            let jdev_0_1 = bjt0_jac[1];
            let jdev_1_0 = bjt0_jac[2];
            let jdev_1_1 = bjt0_jac[3];
            let (i_dev2, i_dev3, bjt1_jac) = bjt_evaluate(
                v_d2,
                v_d3,
                state.device_1_is,
                state.device_1_vt,
                DEVICE_1_NF,
                DEVICE_1_NR,
                state.device_1_bf,
                state.device_1_br,
                DEVICE_1_SIGN,
                DEVICE_1_USE_GP,
                DEVICE_1_VAF,
                DEVICE_1_VAR,
                DEVICE_1_IKF,
                DEVICE_1_IKR,
                DEVICE_1_ISE,
                DEVICE_1_NE,
                DEVICE_1_ISC,
                DEVICE_1_NC,
            );
            let jdev_2_2 = bjt1_jac[0];
            let jdev_2_3 = bjt1_jac[1];
            let jdev_3_2 = bjt1_jac[2];
            let jdev_3_3 = bjt1_jac[3];
            let i_dev4 = diode_current(v_d4, state.device_2_is, state.device_2_n_vt);
            let jdev_4_4 = diode_conductance(v_d4, state.device_2_is, state.device_2_n_vt);

            let f0 = i_nl[0] - i_dev0;
            let f1 = i_nl[1] - i_dev1;
            let f2 = i_nl[2] - i_dev2;
            let f3 = i_nl[3] - i_dev3;
            let f4 = i_nl[4] - i_dev4;

            let j0_0 = 1.0 - jdev_0_0 * state.k_be[0][0] - jdev_0_1 * state.k_be[1][0];
            let j0_1 = 0.0 - jdev_0_0 * state.k_be[0][1] - jdev_0_1 * state.k_be[1][1];
            let j0_2 = 0.0 - jdev_0_0 * state.k_be[0][2] - jdev_0_1 * state.k_be[1][2];
            let j0_3 = 0.0 - jdev_0_0 * state.k_be[0][3] - jdev_0_1 * state.k_be[1][3];
            let j0_4 = 0.0 - jdev_0_0 * state.k_be[0][4] - jdev_0_1 * state.k_be[1][4];
            let j1_0 = 0.0 - jdev_1_0 * state.k_be[0][0] - jdev_1_1 * state.k_be[1][0];
            let j1_1 = 1.0 - jdev_1_0 * state.k_be[0][1] - jdev_1_1 * state.k_be[1][1];
            let j1_2 = 0.0 - jdev_1_0 * state.k_be[0][2] - jdev_1_1 * state.k_be[1][2];
            let j1_3 = 0.0 - jdev_1_0 * state.k_be[0][3] - jdev_1_1 * state.k_be[1][3];
            let j1_4 = 0.0 - jdev_1_0 * state.k_be[0][4] - jdev_1_1 * state.k_be[1][4];
            let j2_0 = 0.0 - jdev_2_2 * state.k_be[2][0] - jdev_2_3 * state.k_be[3][0];
            let j2_1 = 0.0 - jdev_2_2 * state.k_be[2][1] - jdev_2_3 * state.k_be[3][1];
            let j2_2 = 1.0 - jdev_2_2 * state.k_be[2][2] - jdev_2_3 * state.k_be[3][2];
            let j2_3 = 0.0 - jdev_2_2 * state.k_be[2][3] - jdev_2_3 * state.k_be[3][3];
            let j2_4 = 0.0 - jdev_2_2 * state.k_be[2][4] - jdev_2_3 * state.k_be[3][4];
            let j3_0 = 0.0 - jdev_3_2 * state.k_be[2][0] - jdev_3_3 * state.k_be[3][0];
            let j3_1 = 0.0 - jdev_3_2 * state.k_be[2][1] - jdev_3_3 * state.k_be[3][1];
            let j3_2 = 0.0 - jdev_3_2 * state.k_be[2][2] - jdev_3_3 * state.k_be[3][2];
            let j3_3 = 1.0 - jdev_3_2 * state.k_be[2][3] - jdev_3_3 * state.k_be[3][3];
            let j3_4 = 0.0 - jdev_3_2 * state.k_be[2][4] - jdev_3_3 * state.k_be[3][4];
            let j4_0 = 0.0 - jdev_4_4 * state.k_be[4][0];
            let j4_1 = 0.0 - jdev_4_4 * state.k_be[4][1];
            let j4_2 = 0.0 - jdev_4_4 * state.k_be[4][2];
            let j4_3 = 0.0 - jdev_4_4 * state.k_be[4][3];
            let j4_4 = 1.0 - jdev_4_4 * state.k_be[4][4];

            let mut a = [
                [j0_0, j0_1, j0_2, j0_3, j0_4],
                [j1_0, j1_1, j1_2, j1_3, j1_4],
                [j2_0, j2_1, j2_2, j2_3, j2_4],
                [j3_0, j3_1, j3_2, j3_3, j3_4],
                [j4_0, j4_1, j4_2, j4_3, j4_4],
            ];
            let mut b = [f0, f1, f2, f3, f4];
            let mut singular = false;
            for col in 0..5 {
                let mut max_row = col;
                let mut max_val = a[col][col].abs();
                for row in (col + 1)..5 {
                    if a[row][col].abs() > max_val {
                        max_val = a[row][col].abs();
                        max_row = row;
                    }
                }
                if max_val < 1e-15 {
                    singular = true;
                    break;
                }
                if max_row != col {
                    a.swap(col, max_row);
                    b.swap(col, max_row);
                }
                let pivot = a[col][col];
                for row in (col + 1)..5 {
                    let factor = a[row][col] / pivot;
                    for j in (col + 1)..5 {
                        a[row][j] -= factor * a[col][j];
                    }
                    b[row] -= factor * b[col];
                }
            }
            if !singular {
                for i in (0..5).rev() {
                    let mut sum = b[i];
                    for j in (i + 1)..5 {
                        sum -= a[i][j] * b[j];
                    }
                    if a[i][i].abs() < 1e-15 {
                        singular = true;
                        break;
                    }
                    b[i] = sum / a[i][i];
                }
            }
            if !singular {
                let delta0 = b[0];
                let delta1 = b[1];
                let delta2 = b[2];
                let delta3 = b[3];
                let delta4 = b[4];
                let dv0 = -(state.k_be[0][0] * delta0
                    + state.k_be[0][1] * delta1
                    + state.k_be[0][2] * delta2
                    + state.k_be[0][3] * delta3
                    + state.k_be[0][4] * delta4);
                let dv1 = -(state.k_be[1][0] * delta0
                    + state.k_be[1][1] * delta1
                    + state.k_be[1][2] * delta2
                    + state.k_be[1][3] * delta3
                    + state.k_be[1][4] * delta4);
                let dv2 = -(state.k_be[2][0] * delta0
                    + state.k_be[2][1] * delta1
                    + state.k_be[2][2] * delta2
                    + state.k_be[2][3] * delta3
                    + state.k_be[2][4] * delta4);
                let dv3 = -(state.k_be[3][0] * delta0
                    + state.k_be[3][1] * delta1
                    + state.k_be[3][2] * delta2
                    + state.k_be[3][3] * delta3
                    + state.k_be[3][4] * delta4);
                let dv4 = -(state.k_be[4][0] * delta0
                    + state.k_be[4][1] * delta1
                    + state.k_be[4][2] * delta2
                    + state.k_be[4][3] * delta3
                    + state.k_be[4][4] * delta4);
                let mut alpha = [1.0_f64; 5];
                let mut any_limited = false;
                if dv0.abs() > 1e-4 {
                    let v_lim = pnjlim(v_d0 + dv0, v_d0, state.device_0_vt, DEVICE_0_VCRIT);
                    let ratio = ((v_lim - v_d0) / dv0).max(0.01);
                    if ratio < alpha[0] {
                        alpha[0] = ratio;
                        if ratio < 1.0 {
                            any_limited = true;
                        }
                    }
                }
                if dv1.abs() > 1e-4 {
                    let v_lim = pnjlim(v_d1 + dv1, v_d1, state.device_0_vt, DEVICE_0_VCRIT);
                    let ratio = ((v_lim - v_d1) / dv1).max(0.01);
                    if ratio < alpha[1] {
                        alpha[1] = ratio;
                        if ratio < 1.0 {
                            any_limited = true;
                        }
                    }
                }
                if dv2.abs() > 1e-4 {
                    let v_lim = pnjlim(v_d2 + dv2, v_d2, state.device_1_vt, DEVICE_1_VCRIT);
                    let ratio = ((v_lim - v_d2) / dv2).max(0.01);
                    if ratio < alpha[2] {
                        alpha[2] = ratio;
                        if ratio < 1.0 {
                            any_limited = true;
                        }
                    }
                }
                if dv3.abs() > 1e-4 {
                    let v_lim = pnjlim(v_d3 + dv3, v_d3, state.device_1_vt, DEVICE_1_VCRIT);
                    let ratio = ((v_lim - v_d3) / dv3).max(0.01);
                    if ratio < alpha[3] {
                        alpha[3] = ratio;
                        if ratio < 1.0 {
                            any_limited = true;
                        }
                    }
                }
                if dv4.abs() > 1e-4 {
                    let v_lim = pnjlim(v_d4 + dv4, v_d4, state.device_2_n_vt, DEVICE_2_VCRIT);
                    let ratio = ((v_lim - v_d4) / dv4).max(0.01);
                    if ratio < alpha[4] {
                        alpha[4] = ratio;
                        if ratio < 1.0 {
                            any_limited = true;
                        }
                    }
                }
                let mut alpha_scalar =
                    alpha[0].min(alpha[1].min(alpha[2].min(alpha[3].min(alpha[4]))));
                // Global voltage backstop: limit max voltage change to 3.5V
                let max_dv = (dv0 * alpha_scalar)
                    .abs()
                    .max((dv1 * alpha_scalar).abs())
                    .max((dv2 * alpha_scalar).abs())
                    .max((dv3 * alpha_scalar).abs())
                    .max((dv4 * alpha_scalar).abs());
                if max_dv > 3.500000 {
                    alpha_scalar *= (3.500000 / max_dv).max(0.1);
                }
                i_nl[0] -= alpha_scalar * delta0;
                i_nl[1] -= alpha_scalar * delta1;
                i_nl[2] -= alpha_scalar * delta2;
                i_nl[3] -= alpha_scalar * delta3;
                i_nl[4] -= alpha_scalar * delta4;
                // Convergence check (SPICE RELTOL=0.001, VNTOL=1e-6)
                if !any_limited {
                    let mut nr_converged = true;
                    {
                        let step = dv0 * alpha_scalar;
                        let v_new = v_d0 + step;
                        let threshold = 1e-3 * v_d0.abs().max(v_new.abs()) + 1e-6;
                        if !(step.abs() <= threshold) {
                            nr_converged = false;
                        }
                    }
                    {
                        let step = dv1 * alpha_scalar;
                        let v_new = v_d1 + step;
                        let threshold = 1e-3 * v_d1.abs().max(v_new.abs()) + 1e-6;
                        if !(step.abs() <= threshold) {
                            nr_converged = false;
                        }
                    }
                    {
                        let step = dv2 * alpha_scalar;
                        let v_new = v_d2 + step;
                        let threshold = 1e-3 * v_d2.abs().max(v_new.abs()) + 1e-6;
                        if !(step.abs() <= threshold) {
                            nr_converged = false;
                        }
                    }
                    {
                        let step = dv3 * alpha_scalar;
                        let v_new = v_d3 + step;
                        let threshold = 1e-3 * v_d3.abs().max(v_new.abs()) + 1e-6;
                        if !(step.abs() <= threshold) {
                            nr_converged = false;
                        }
                    }
                    {
                        let step = dv4 * alpha_scalar;
                        let v_new = v_d4 + step;
                        let threshold = 1e-3 * v_d4.abs().max(v_new.abs()) + 1e-6;
                        if !(step.abs() <= threshold) {
                            nr_converged = false;
                        }
                    }
                    if nr_converged {
                        state.last_nr_iterations = _iter as u32;
                        break;
                    }
                }
            } else {
                i_nl[0] -= (f0 * 0.5).clamp(-0.01, 0.01);
                i_nl[1] -= (f1 * 0.5).clamp(-0.01, 0.01);
                i_nl[2] -= (f2 * 0.5).clamp(-0.01, 0.01);
                i_nl[3] -= (f3 * 0.5).clamp(-0.01, 0.01);
                i_nl[4] -= (f4 * 0.5).clamp(-0.01, 0.01);
            }
        }

        // Recover full v from BE solve
        v = v_pred_be;
        for i in 0..N {
            for j in 0..M {
                v[i] += state.s_ni_be[i][j] * i_nl[j];
            }
        }
    }

    // NaN/Inf AND finite-but-implausible-magnitude check BEFORE state
    // update — prevents corruption of v_prev/i_nl_prev. A saturated solve
    // (exp() clamp, near-singular LU) can produce a huge-but-finite value
    // that bypasses is_finite() and would otherwise propagate forever.
    // Mirrors the DK-path reset in templates/rust/process_sample.rs.tera (Step 7).
    let v_is_finite = v.iter().all(|x| x.is_finite());
    if !v_is_finite || v.iter().any(|x| x.abs() > STATE_MAX_PLAUSIBLE_MAGNITUDE) {
        state.v_prev = state.dc_operating_point;
        state.i_nl_prev = DC_NL_I;
        state.i_nl_prev_prev = DC_NL_I;
        state.input_prev = 0.0;
        state.injections_prev = [0.0; NUM_INJECT];
        if v_is_finite {
            state.diag_magnitude_reset_count += 1;
        } else {
            state.diag_nan_reset_count += 1;
        }
        let mut nan_out = [0.0f64; NUM_OUTPUTS];
        nan_out[0] = 4.36625634132295470e0;
        let mut nan_taps = [0.0f64; NUM_TAP];
        nan_taps[0] = 1.34136800666353189e1;
        nan_taps[1] = 1.18746439971943616e1;
        return (nan_out, nan_taps);
    }

    // State update
    state.v_prev = v;
    state.input_prev = input;
    state.injections_prev = injections;
    state.i_nl_prev_prev = state.i_nl_prev;
    state.i_nl_prev = i_nl;

    // Region-exit characterization: samples where a pentode's grid
    // conducts (Vgk > 0) or a BJT saturates (Vbc forward) — the regions
    // the grid-off / forward-active reductions assume are never entered.
    if (v[2] - v[0]) > 0.0 {
        state.diag_region_exit_count += 1;
    }
    if (v[4] - v[0]) > 0.0 {
        state.diag_region_exit_count += 1;
    }
    // Extract outputs, DC blocking, and scaling
    let mut output = [0.0f64; NUM_OUTPUTS];
    for out_idx in 0..NUM_OUTPUTS {
        let raw_out = v[OUTPUT_NODES[out_idx]];
        let raw_out = if raw_out.is_finite() { raw_out } else { 0.0 };
        let scaled = raw_out * OUTPUT_SCALES[out_idx];
        let abs_out = scaled.abs();
        if abs_out > state.diag_peak_output {
            state.diag_peak_output = abs_out;
        }
        output[out_idx] = if scaled.is_finite() { scaled } else { 0.0 };
    }
    let mut taps = [0.0f64; NUM_TAP];
    for t in 0..NUM_TAP {
        let raw = v[TAP_NODES[t]];
        taps[t] = if raw.is_finite() { raw } else { 0.0 };
    }
    (output, taps)
}

/// Process a single audio sample through the circuit.
///
/// `injections_inner[0]` supplies the `.inject` values for this sample. Returns
/// the outputs plus the RAW `.tap` node voltages `taps_inner[0]`. In a feedback
/// loop, `injections_inner` must be derived from a PRIOR sample's tap — this is
/// >=1 sample of delay by construction.
#[inline]
pub fn process_sample(
    input: f64,
    injections_inner: &[[f64; NUM_INJECT]; OVERSAMPLING_FACTOR],
    state: &mut CircuitState,
) -> ([f64; NUM_OUTPUTS], [[f64; NUM_TAP]; OVERSAMPLING_FACTOR]) {
    let input = if input.is_finite() {
        input.clamp(-100.0, 100.0)
    } else {
        0.0
    };
    let (output, tap) = process_sample_inner(input, injections_inner[0], state);
    (output, [tap])
}
